  document.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup',' ','a','d','x'].includes(k))e.preventDefault();if(k==='arrowleft'||k==='a')keys.left=true;if(k==='arrowright'||k==='d')keys.right=true;if(k===' '||k==='arrowup'||k==='w'){keys.jump=true;if(!e.repeat)jump();}if(k==='x')attackBoss();});
  document.addEventListener('keyup',e=>{const k=e.key.toLowerCase();if(k==='arrowleft'||k==='a')keys.left=false;if(k==='arrowright'||k==='d')keys.right=false;if(k===' '||k==='arrowup'||k==='w')keys.jump=false;if(k==='x')fireHeld=false;});
  document.querySelectorAll('[data-control]').forEach(button=>{const key=button.dataset.control,down=e=>{e.preventDefault();if(key==='jump'){keys.jump=true;jump();}else if(key==='attack')attackBoss();else keys[key]=true;},up=e=>{e.preventDefault();if(key==='attack')fireHeld=false;else if(key==='jump')keys.jump=false;else keys[key]=false;};button.addEventListener('pointerdown',down);button.addEventListener('pointerup',up);button.addEventListener('pointercancel',up);button.addEventListener('pointerleave',up);});
